{
   "title": "CSCI-529: Seminar in Data Science for Computer Scientists",
   "learningObjectives": [
     "Define the core components of a data analysis workflow and explain how preprocessing, modeling, and evaluation stages interact.",
     "Distinguish between supervised and unsupervised learning methods and match them to appropriate analytical questions and evaluation metrics.",
     "Apply data quality analysis techniques to identify missingness, duplicates, and distribution shift, and explain how these factors impact model general"
   ],
   "beats": [
     {
       "title": "Workflow Architecture",
       "claim": "Data-analysis workflows separate data preparation, exploratory analysis, training, validation, testing, model selection, and evaluation.",
       "example": "A pipeline begins by cleaning raw CSV files, then splits them into training and validation sets before fitting a classifier.",
       "visualDirection": "Display a horizontal flowchart with seven labeled nodes connected by arrows, showing the progression from data preparation to evaluation.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {
       "title": "Supervised Learning Foundations",
       "claim": "Supervised methods learn mappings from examples paired with target labels.",
       "example": "Training a logistic regression model on labeled spam emails where the label indicates whether each message is spam or not.",
       "visualDirection": "Show a split-screen diagram: left side shows unlabeled data points, right side shows the same points with colored target labels, connected by a learning arrow.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {

       "title": "Unsupervised Learning Foundations",
       "claim": "Unsupervised methods identify structure without targets.",
       "example": "Applying k-means clustering to customer purchase data to group users by spending patterns without predefined categories.",
       "visualDirection": "Render a scatter plot of data points with colored clusters forming around natural groupings, labeled as 'no target labels'.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {
       "title": "Preprocessing Constraints",
       "claim": "Preprocessing must be fitted only on permitted training data to avoid leakage.",
       "example": "Scaling features using the mean and standard deviation calculated exclusively from the training set before applying to validation data.",
       "visualDirection": "Illustrate a pipeline where a 'fit' step occurs on the training set, and a 'transform' step applies the same parameters to the validation set, with a warning icon blocking cross-contamination.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {
       "title": "Pipeline Consistency",
       "claim": "Pipelines combine transformations and estimators so the same operations are applied consistently.",
       "example": "A single pipeline object that chains standardization, imputation, and model fitting, ensuring identical operations run during training and prediction.",
       "visualDirection": "Draw a rectangular block labeled 'Pipeline' containing three stacked sub-blocks (transform, impute, estimator) with input and output arrows, emphasizing unified execution.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {
       "title": "Cross-Validation Mechanics",
       "claim": "Cross-validation repeats training and validation across defined splits.",
       "example": "Using five-fold cross-validation where the dataset is partitioned into five subsets, each serving as a validation set once while the others train the model.",
       "visualDirection": "Show a circular diagram with five segments, each labeled with a fold number, and arrows indicating rotation through training and validation phases.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {
       "title": "Evaluation Alignment",
       "claim": "Evaluation must match the task and the cost of errors, while distribution shift, missing data, overfitting, and unexamined sampling choices can invalidate conclusions.",
       "example": "Using precision and recall for fraud detection because false negatives carry higher cost than false positives, and adjusting thresholds based on class imbalance.",
       "visualDirection": "Present a decision matrix comparing true/false positives and negatives, with cost weights applied to each quadrant to show evaluation trade-offs.",
       "sourceIds": ["scikit-learn-user-guide"]
     },
     {
       "title": "Data Quality Analysis",
       "claim": "Data quality analysis makes missingness, duplicates, inconsistent representation, integrity constraints, sampling, and update behavior explicit.",
       "example": "Running a data profiling script that reports null counts, duplicate row percentages, and value distribution shifts across time periods.",
       "visualDirection": "Display a dashboard mockup with four metric cards: 'Missingness %', 'Duplicate Rate', 'Value Range', and 'Update Frequency', each with a trend line.",
       "sourceIds": ["postgresql-documentation"]
     },
     {
       "title": "Query and Storage Impact",
       "claim": "Query planning and physical storage affect performance without changing logical query meaning.",
       "example": "Adding a B-tree index on a frequently filtered column speeds up SELECT operations while preserving the exact same SQL result set.",
       "visualDirection": "Show a before-and-after comparison: left side shows a full table scan with slow execution time, right side shows an index lookup with faster execution time and identical output rows.",
       "sourceIds": ["postgresql-documentation"]
     },
     {
       "title": "Practical Analysis Checklist",
       "claim": "Analytical work should preserve provenance from captured data through cleaning, transformation, grouping, modeling, visualization, and reporting.",
       "example": "Maintaining a versioned data lineage log that tracks each transformation step, model parameters, and visualization settings for reproducible research.",
       "visualDirection": "List a checklist with six checkboxes: 'Provenance Tracked', 'Transformations Documented', 'Model Parameters Logged', 'Visualization Settings Saved', 'Reporting Format Standardized', 'Reproducibility Verified'.",
       "sourceIds": ["postgresql-documentation"]
     }
   ]
}
